contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        bool openReverted;
        c.OpenToThePublic(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { openReverted = true; } else { openReverted = false; }

        bool wagerReverted;
        c.wager{value: amount}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { wagerReverted = true; } else { wagerReverted = false; }

        assert(!openReverted || wagerReverted);
    }

    receive() external payable {}
}

